function wireUniforms(){
 $("[data-uniform-new]")?.addEventListener("click",()=>{uniformEditingId=null;uniformDraftRows=[uniformBlankRow()];uniformFormOpen=true;render()});
 $("[data-uniform-cancel]")?.addEventListener("click",()=>{uniformFormOpen=false;uniformEditingId=null;uniformDraftRows=[];render()});
 $("[data-uniform-add]")?.addEventListener("click",()=>{uniformDraftRows.push(uniformBlankRow());render()});
 document.querySelectorAll("[data-uniform-remove]").forEach(b=>b.addEventListener("click",()=>{uniformDraftRows.splice(Number(b.dataset.uniformRemove),1);if(!uniformDraftRows.length)uniformDraftRows.push(uniformBlankRow());render()}));
 document.querySelectorAll("[data-uniform-field]").forEach(input=>input.addEventListener("input",()=>{const i=Number(input.dataset.row),key=input.dataset.uniformField;if(!uniformDraftRows[i])return;uniformDraftRows[i][key]=["unitPrice","quantity"].includes(key)?n(input.value):input.value;const row=document.querySelector('[data-uniform-row-total="'+i+'"]');if(row)row.textContent=brl(n(uniformDraftRows[i].unitPrice)*n(uniformDraftRows[i].quantity));const total=$("#uniform-grand-total");if(total)total.textContent=brl(uniformDraftRows.reduce((sum,x)=>sum+n(x.unitPrice)*n(x.quantity),0))}));
 $("#uniform-form")?.addEventListener("submit",e=>{e.preventDefault();if(!isGun())return;const f=new FormData(e.currentTarget),items=uniformDraftRows.map(x=>({...x,description:String(x.description||"").trim(),size:String(x.size||"").trim(),code:String(x.code||"").trim(),supplier:String(x.supplier||"").trim(),unitPrice:n(x.unitPrice),quantity:n(x.quantity)})).filter(x=>x.description||x.size||x.code||x.supplier||x.unitPrice||x.quantity);if(!items.length)return toast("Adicione pelo menos um item à projeção.");if(items.some(x=>x.quantity<0||x.unitPrice<0||!Number.isFinite(x.quantity)||!Number.isFinite(x.unitPrice)))return toast("Confira as quantidades e os valores.");const month=n(f.get("month")),year=n(f.get("year"));if(month<1||month>12||year<2024||year>2100)return toast("Informe um mês e ano válidos.");data.adminUniformProjections??=[];const old=data.adminUniformProjections.find(x=>x.id===uniformEditingId);const record={id:uniformEditingId||"uniform-"+Date.now()+"-"+Math.random().toString(36).slice(2,7),month,year,items,updatedAt:new Date().toISOString(),createdAt:old?.createdAt||new Date().toISOString()};if(old)data.adminUniformProjections=data.adminUniformProjections.map(x=>x.id===old.id?record:x);else data.adminUniformProjections.push(record);audit(old?"Projeção de uniformes atualizada":"Projeção de uniformes criada",month+"/"+year+" · "+brl(uniformProjectionTotal(record)));save();uniformFormOpen=false;uniformEditingId=null;uniformDraftRows=[];toast("Projeção salva com sucesso.");render()});
 document.querySelectorAll("[data-uniform-edit]").forEach(b=>b.addEventListener("click",()=>{const p=(data.adminUniformProjections||[]).find(x=>x.id===b.dataset.uniformEdit);if(!p)return;uniformEditingId=p.id;uniformDraftRows=(p.items||[]).map(x=>({...uniformBlankRow(),...x}));uniformFormOpen=true;render()}));
 document.querySelectorAll("[data-uniform-print]").forEach(b=>b.addEventListener("click",()=>{const p=(data.adminUniformProjections||[]).find(x=>x.id===b.dataset.uniformPrint);if(p)openUniformPrint(p)}));
 document.querySelectorAll("[data-uniform-share]").forEach(b=>b.addEventListener("click",()=>{const p=(data.adminUniformProjections||[]).find(x=>x.id===b.dataset.uniformShare);if(p)shareUniform(p)}));
 document.querySelectorAll("[data-uniform-delete]").forEach(b=>b.addEventListener("click",()=>{const p=(data.adminUniformProjections||[]).find(x=>x.id===b.dataset.uniformDelete);if(!p||!confirm("Excluir esta projeção de uniformes?"))return;data.adminUniformProjections=data.adminUniformProjections.filter(x=>x.id!==p.id);audit("Projeção de uniformes excluída",p.month+"/"+p.year);save();render()}));
}


const expenseGroups=[
 ["Serviços Externos",["Serviços com Segurança","Custos de Comissões","Serviços com Mc Entrega","Outros Serviços Externos"]],
 ["Manutenção e Reparos",["Salários Manutenção","Equipamentos de Manutenção","Conservação de Restaurante","Outros"]],
 ["Serviços Públicos",["Eletricidade","Outros Gastos Públicos"]],
 ["Serviços TI",["Telecomunicação","Suporte ao Campo","Help Desk","Back office"]]
];
const expenseStandalone=["Publicidade","Promoção","Uniformes","Insumos Operacionais","Despesas de Material de Escritório","Diferença de Caixa","Gastos Pré Abertura","Outros Gastos Controláveis"];
const expenseCategories=[...expenseStandalone,...expenseGroups.flatMap(g=>g[1])];
const escAdmin=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const brl=v=>n(v).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
function expenseCategoryOptions(selected=""){
 return expenseStandalone.map(x=>'<option value="'+escAdmin(x)+'" '+(selected===x?"selected":"")+'>'+escAdmin(x)+'</option>').join("")+
 expenseGroups.map(([group,items])=>'<optgroup label="'+escAdmin(group)+'">'+items.map(x=>'<option value="'+escAdmin(x)+'" '+(selected===x?"selected":"")+'>'+escAdmin(x)+'</option>').join("")+'</optgroup>').join("");
}
function expensesPage(){
 data.adminExpenses??=[];
 const rows=data.adminExpenses.slice().sort((a,b)=>(b.dueDate||"").localeCompare(a.dueDate||"")||(b.createdAt||"").localeCompare(a.createdAt||""));
 const total=rows.reduce((s,x)=>s+n(x.amount),0),paid=rows.filter(x=>x.status==="Pago").reduce((s,x)=>s+n(x.amount),0),pending=total-paid;
 const table=rows.length?rows.map(x=>'<tr><td>'+escAdmin(x.description)+'</td><td>'+escAdmin(x.category)+'</td><td>'+escAdmin(x.supplier||"—")+'</td><td>'+escAdmin(x.dueDate?new Date(x.dueDate+"T12:00:00").toLocaleDateString("pt-BR"):"—")+'</td><td class="expense-money">'+brl(x.amount)+'</td><td><span class="expense-status '+(x.status==="Pago"?"paid":"pending")+'">'+escAdmin(x.status)+'</span></td><td><button class="expense-action" data-expense-toggle="'+escAdmin(x.id)+'">'+(x.status==="Pago"?"Reabrir":"Marcar pago")+'</button> <button class="expense-action delete" data-expense-delete="'+escAdmin(x.id)+'" aria-label="Excluir lançamento">Excluir</button></td></tr>').join(""):'<tr><td colspan="7" class="expense-empty">Nenhuma despesa lançada ainda.</td></tr>';
 return adminShell('<div class="expense-summary"><article><small>Total lançado</small><b>'+brl(total)+'</b></article><article><small>Total pago</small><b>'+brl(paid)+'</b></article><article><small>Em aberto</small><b>'+brl(pending)+'</b></article></div><section class="card expense-form-card"><div class="expense-heading"><div><span class="eyebrow">NOVO REGISTRO</span><h2>Lançar despesa</h2><p>Cadastre a nota ou conta e classifique no departamento correto.</p></div></div><form id="expense-form" class="expense-form"><label>Descrição da despesa<input name="description" required maxlength="120" placeholder="Ex.: Conta de água de novembro"></label><label>Categoria / departamento<select name="category" required><option value="">Selecione a categoria</option>'+expenseCategoryOptions()+'</select></label><label>Fornecedor / favorecido<input name="supplier" maxlength="100" placeholder="Nome do fornecedor"></label><label>Valor (R$)<input name="amount" type="number" min="0.01" step="0.01" required placeholder="0,00"></label><label>Vencimento<input name="dueDate" type="date" required></label><label>Situação<select name="status"><option value="Pendente">Pendente</option><option value="Pago">Pago</option></select></label><div class="expense-form-actions"><button class="btn primary" type="submit">Salvar lançamento</button></div></form></section><section class="card expense-list-card"><div class="expense-list-heading"><div><h2>Lançamentos de despesas</h2><p>Os totais por departamento são calculados automaticamente.</p></div><button class="btn secondary" type="button" data-expense-export>Exportar CSV</button></div><div class="expense-table-wrap"><table class="expense-table"><thead><tr><th>Descrição</th><th>Categoria</th><th>Fornecedor</th><th>Vencimento</th><th>Valor</th><th>Situação</th><th>Ações</th></tr></thead><tbody>'+table+'</tbody></table></div></section><section class="card expense-totals-card"><h2>Resumo por departamento</h2>'+expenseGroups.map(([group,items])=>{const sum=items.reduce((s,k)=>s+rows.filter(x=>x.category===k).reduce((v,x)=>v+n(x.amount),0),0);return '<div class="expense-total-row"><b>'+escAdmin(group)+'</b><strong>'+brl(sum)+'</strong></div>'}).join("")+'<div class="expense-total-row grand"><b>TOTAL GASTOS CONTROLÁVEIS</b><strong>'+brl(total)+'</strong></div></section>');
}
function wireAdmin(){
 $("#expense-form")?.addEventListener("submit",e=>{e.preventDefault();if(!isGun())return;const f=new FormData(e.currentTarget),amount=Number(f.get("amount"));if(!Number.isFinite(amount)||amount<=0)return toast("Informe um valor válido.");const category=String(f.get("category")||"");if(!expenseCategories.includes(category))return toast("Selecione uma categoria válida.");data.adminExpenses??=[];data.adminExpenses.push({id:"expense-"+Date.now()+"-"+Math.random().toString(36).slice(2,7),description:String(f.get("description")||"").trim(),category,supplier:String(f.get("supplier")||"").trim(),amount,dueDate:String(f.get("dueDate")||""),status:String(f.get("status")||"Pendente"),createdAt:new Date().toISOString(),createdBy:window.IPM_AUTH?.profile?.username||""});audit("Despesa lançada",category+" · "+brl(amount));save();toast("Despesa salva com sucesso.");render()});
 document.querySelectorAll("[data-expense-toggle]").forEach(b=>b.onclick=()=>{if(!isGun())return;const item=(data.adminExpenses||[]).find(x=>x.id===b.dataset.expenseToggle);if(!item)return;item.status=item.status==="Pago"?"Pendente":"Pago";item.updatedAt=new Date().toISOString();audit("Situação da despesa alterada",item.description+" · "+item.status);save();render()});
 document.querySelectorAll("[data-expense-delete]").forEach(b=>b.onclick=()=>{if(!isGun())return;const item=(data.adminExpenses||[]).find(x=>x.id===b.dataset.expenseDelete);if(!item||!confirm("Excluir o lançamento \""+item.description+"\"?"))return;data.adminExpenses=data.adminExpenses.filter(x=>x.id!==item.id);audit("Despesa excluída",item.description);save();render()});
 $("[data-expense-export]")?.addEventListener("click",()=>{const rows=data.adminExpenses||[];const csv=[["Descrição","Categoria","Fornecedor","Vencimento","Valor","Situação"],...rows.map(x=>[x.description,x.category,x.supplier,x.dueDate,x.amount,x.status])].map(r=>r.map(v=>'"'+String(v??"").replace(/"/g,'""')+'"').join(";")).join("\r\n");const blob=new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="lancamentos-despesas-ipm.csv";a.click();URL.revokeObjectURL(url)});
}

