 document.querySelectorAll("[data-inter-rate]").forEach(el=>el.addEventListener("change",()=>{const k=el.dataset.interRate;intermitenteDraft.days[k]??={qty:0};intermitenteDraft.days[k].rate=n(el.value);const d=intermitenteDraft.days[k],total=document.querySelector('[data-inter-total="'+k+'"]');if(total)total.textContent=brl(n(d.qty)*n(d.rate));refresh()}));
