 return adminShell('<div class="page-intro"><div><span class="eyebrow">GESTÃO ADMINISTRATIVA</span><h2>Projeção de Mercado Livre</h2><p>Controle dos produtos planejados para compra.</p></div></div>'+editor+(form?'':'<div class="uniform-total-panel"><span>'+rows.length+' itens cadastrados · '+fmt(qty)+' unidades</span><strong>'+brl(total)+'</strong><div class="uniform-card-actions"><button type="button" data-ml-print>Imprimir / Salvar PDF</button><button type="button" data-ml-share>Compartilhar</button></div></div>')+list);
