 $("#ml-form")?.addEventListener("submit",e=>{e.preventDefault();if(!isGun())return;const items=mercadoLivreDraftRows.map(x=>({...x,name:String(x.name||"").trim(),url:String(x.url||"").trim(),price:n(x.price),quantity:Math.floor(n(x.quantity))}));if(!items.length||items.some(x=>!x.name||!(x.url.startsWith("https://")||x.url.startsWith("http://"))||!Number.isFinite(x.price)||x.price<=0||!Number.isInteger(x.quantity)||x.quantity<1))return toast("Confira os dados de todos os produtos.");data.adminMercadoLivreItems??=[];const now=new Date().toISOString(),oldId=mercadoLivreEditingId,old=data.adminMercadoLivreItems.find(x=>x.id===oldId);const saved=items.map((x,i)=>({...x,id:oldId&&i===0?oldId:"ml-"+Date.now()+"-"+i+"-"+Math.random().toString(36).slice(2,6),listId:old?.listId||oldId||"ml-list-"+Date.now(),createdAt:old?.createdAt||now,updatedAt:now}));if(oldId)data.adminMercadoLivreItems=data.adminMercadoLivreItems.filter(x=>x.id!==oldId);data.adminMercadoLivreItems.push(...saved);audit("Lista da projeção Mercado Livre salva",saved.length+" itens · "+brl(mlTotal(saved)));save();mercadoLivreDraftRows=[];mercadoLivreEditingId=null;mercadoLivreFormOpen=false;toast("Lista salva.");render()});
 document.querySelectorAll("[data-ml-edit]").forEach(b=>b.onclick=()=>{const x=(data.adminMercadoLivreItems||[]).find(y=>y.id===b.dataset.mlEdit);if(x){mercadoLivreEditingId=x.id;mercadoLivreDraftRows=[{...mlBlankRow(),...x}];mercadoLivreFormOpen=true;render()}});
 document.querySelectorAll("[data-ml-delete]").forEach(b=>b.onclick=()=>{const x=(data.adminMercadoLivreItems||[]).find(y=>y.id===b.dataset.mlDelete);if(!x||!confirm("Excluir o produto "+x.name+"?"))return;data.adminMercadoLivreItems=data.adminMercadoLivreItems.filter(y=>y.id!==x.id);audit("Item da projeção Mercado Livre excluído",x.name);save();render()});
